"use strict";const e=require("../utils/request.js");exports.getCodeApi=t=>e.request({method:"GET",url:"/portal/user/send_code",data:{phone:t}}),exports.getUserInfoApi=()=>e.request({method:"GET",url:"/portal/user/login_info/get"}),exports.loginByCodeApi=({phone:t,code:o})=>e.request({method:"POST",url:"/portal/user/login/code",data:{phone:t,code:o}}),exports.loginByWxApi=t=>e.request({method:"POST",url:"/portal/user/login/wechat/code",data:{code:t}}),exports.putUserInfoApi=({userId:t,nickName:o,avatar:r})=>e.request({method:"POST",url:"/portal/user/edit",data:{userId:t,nickName:o,avatar:r}});
